@dataclass(frozen=True)
class EngineProcessCheck:
    script: str
    marker: str
    completion: str
    support: tuple = ()
    arguments: tuple = ()
    features: tuple = ()
    primary: bool = False

    def selected(self, feature):
        return feature is None or not self.features or feature in self.features


